/*
LLM针对问题的编程策略的选择错误
应该为数组下标选择实现，而不是多路选择器的实现方式
*/

module TopModule (
  input [1023:0] in,
  input [7:0] sel,
  output [3:0] out
);

  assign out = {in[sel*4+3], in[sel*4+2], in[sel*4+1], in[sel*4+0]};

endmodule


